package audit

import (
	"encoding/json"
	"strings"
	"time"

	"github.com/Crows-Storm/Axis/common/contextx"
	"github.com/Crows-Storm/Axis/common/domain/event"
)

// New maps a consumed wire onto the time-series document.
// operatorID is the in-process principal. A Kafka consumer has none, so a
// non-zero OperatorID field inside the payload is used instead.
// Correlation and causation are the producer's values carried on the record,
// not a causation id generated by the audit process.
func New(wire event.Wire, operatorID uint64) (*AuditEvent, error) {
	if strings.TrimSpace(wire.EventID) == "" || strings.TrimSpace(wire.EventName) == "" {
		return nil, ErrInvalidRecord
	}
	occurred, err := occurredAt(wire.OccurredAt)
	if err != nil {
		return nil, err
	}
	category, payloadOperator := payloadFields(wire.Payload)
	if operatorID == 0 {
		operatorID = payloadOperator
	}
	return &AuditEvent{
		ID:         wire.EventID,
		EventID:    wire.EventID,
		EventName:  wire.EventName,
		OperatorID: operatorID,
		Category:   category,
		Timestamp:  occurred,
		Metadata: Metadata{
			Service:       sourceService(wire),
			AggregateID:   wire.AggregateID,
			CorrelationId: lookup(wire, contextx.MetadataCorrelationID),
			CausationId:   lookup(wire, contextx.MetadataCausationId),
			Payload:       wire.Payload,
		},
	}, nil
}

func occurredAt(raw string) (time.Time, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return time.Now().UTC(), nil
	}
	if t, err := time.Parse(time.RFC3339Nano, raw); err == nil {
		return t.UTC(), nil
	}
	if t, err := time.Parse(time.RFC3339, raw); err == nil {
		return t.UTC(), nil
	}
	return time.Time{}, ErrInvalidRecord
}

func payloadFields(payload []byte) (category string, operatorID uint64) {
	if len(payload) == 0 {
		return "", 0
	}
	var probe struct {
		Category   string `json:"Category"`
		OperatorID uint64 `json:"OperatorID"`
	}
	if err := json.Unmarshal(payload, &probe); err != nil {
		return "", 0
	}
	return probe.Category, probe.OperatorID
}

func sourceService(wire event.Wire) string {
	if v := lookup(wire, event.MetaSourceService); v != "" {
		return v
	}
	return lookup(wire, "x-source-service")
}

func lookup(wire event.Wire, key string) string {
	if wire.Metadata != nil {
		if v := wire.Metadata[key]; v != "" {
			return v
		}
	}
	if wire.Headers != nil {
		return wire.Headers[key]
	}
	return ""
}
